-- [[Improvement - Expand Pokedex species and learnset coverage for excluded PokeAPI slugs]], pass 1 of 2: the 24
-- ordinary species missing from the Pokedex (re-counted 2026-11-22 against PokeAPI's 1025 species: 73 missing, 24
-- ordinary + 49 Legendary/Mythical/Ultra Beast/Paradox -- the Legendaries are pass 2).
--
-- Forms (per the user): a real form the source prints as its own entry gets its own row (Nidoran Female/Male,
-- Wormadam's three cloaks, Lycanroc Day/Dusk/Night); a battle-only or cosmetic form gets one row using its default
-- form (Aegislash Shield, Wishiwashi Solo, Minior Meteor, Palafin Zero, Morpeko Full Belly, Mimikyu, Toxtricity,
-- Indeedee, Oinkologne, Maushold, Squawkabilly, Tatsugiri, Dudunsparce, Meowstic). Pumpkaboo/Gourgeist use the Small
-- size, the only one PTA3Pokedex.pdf prints. 28 rows.
--
-- Sources:
-- * PokeAPI (pokemon + pokemon-species + evolution-chain): types, base stats (round(stat / 10) half up, HP the same
--   x 6), catch rate, egg hatch (floor(hatch_counter / 2) days), growth rate, egg groups, level-up learnset, evolutions
--   -- the same formulas and rules as the 2026-08 expansion batches, the evolution import (20260814110000) and the
--   level-learned fixes (20260918200000).
-- * PTA3Pokedex.pdf (read column by column): Size, Weight, Diet, Habitat, Proficiencies. Habitat "Urban Abandoned" ->
--   Abandoned; a form-qualified proficiency ("Horned (Nidoqueen)") only applies to that species.
-- * Sprites: img.pokemondb.net slugs, each checked to exist before writing.
-- Level-up moves that aren't in the move catalog are skipped (as in every earlier import); ones PTA3 models as
-- Passives go to pokedex_passives. Like the earlier expansion species, no ability passives.
-- Every row is looked up by name (global rows only: campaign_id is null), never by id.

-- New proficiencies the source uses that had no row (same naming pattern as Psychic (Effects), Grass (Melee), ...).

-- Species rows (stats from PokeAPI: round(stat / 10) half up, HP the same x 6; catch rate copied; egg hatch floor(hatch_counter / 2) days).

-- Level-up moves (PokeAPI; lowest level across games, ignoring a spurious level 1 when the same move also has a real level > 1).

-- Level-up "moves" PTA3 models as Passives (same level rule).

-- Egg groups (PokeAPI; no-eggs gives no rows).

-- Diets (source PDF).

-- Habitats (source PDF).

-- Proficiencies (source PDF).

-- Evolution chains: join the relatives' existing chain, or start a new one.
update pokedex set evolution_chain_id = (select evolution_chain_id from pokedex where name = 'Nidorina' and campaign_id is null) where campaign_id is null and name in ('Nidoran (Female)');
update pokedex set evolution_chain_id = (select evolution_chain_id from pokedex where name = 'Nidorino' and campaign_id is null) where campaign_id is null and name in ('Nidoran (Male)');
update pokedex set evolution_chain_id = (select evolution_chain_id from pokedex where name = 'Burmy' and campaign_id is null) where campaign_id is null and name in ('Wormadam (Plant Cloak)', 'Wormadam (Sandy Cloak)', 'Wormadam (Trash Cloak)');
update pokedex set evolution_chain_id = (select evolution_chain_id from pokedex where name = 'Porygon' and campaign_id is null) where campaign_id is null and name in ('Porygon-Z');
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Espurr', 'Meowstic'); end $$;
update pokedex set evolution_chain_id = (select evolution_chain_id from pokedex where name = 'Honedge' and campaign_id is null) where campaign_id is null and name in ('Aegislash');
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Pumpkaboo', 'Gourgeist'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Rockruff', 'Lycanroc (Day)', 'Lycanroc (Dusk)', 'Lycanroc (Night)'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Jangmo-o', 'Hakamo-o', 'Kommo-o'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Toxel', 'Toxtricity'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Lechonk', 'Oinkologne'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Tandemaus', 'Maushold'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Finizen', 'Palafin'); end $$;
do $$ declare cid int; begin insert into evolution_chains default values returning id into cid; update pokedex set evolution_chain_id = cid where campaign_id is null and name in ('Dunsparce', 'Dudunsparce'); end $$;

